#define MAX_H 50
#define MAX_W 50

typedef struct {
    int r, c, bottom, front, right;
} State;

int H, W;
char grid[MAX_H][MAX_W+1];
int visited[MAX_H][MAX_W][7][7][7]; // bottom, front, right each 1..6

// Rolling the die: new bottom, front, right
void roll_north(int b, int f, int r, int *nb, int *nf, int *nr) {
    *nb = f;
    *nf = 7 - b;
    *nr = r;
}

void roll_south(int b, int f, int r, int *nb, int *nf, int *nr) {
    *nb = 7 - f;
    *nf = b;
    *nr = r;
}

void roll_east(int b, int f, int r, int *nb, int *nf, int *nr) {
    *nb = r;
    *nf = f;
    *nr = 7 - b;
}

void roll_west(int b, int f, int r, int *nb, int *nf, int *nr) {
    *nb = 7 - r;
    *nf = f;
    *nr = b;
}

int bfs() {
    // Queue for BFS
    State queue[MAX_H*MAX_W*6*6*6];
    int front = 0, rear = 0;

    // Initial state at (0,0) bottom=6 front=2 right=3
    State start = {0, 0, 6, 2, 3};
    queue[rear++] = start;
    visited[0][0][6][2][3] = 1;

    int dr[] = {-1, 1, 0, 0};
    int dc[] = {0, 0, 1, -1};
    void (*roll_funcs[])(int,int,int,int*,int*,int*) = {
        roll_north, roll_south, roll_east, roll_west
    };

    while (front < rear) {
        State cur = queue[front++];
        int r = cur.r, c = cur.c;
        int b = cur.bottom, f = cur.front, rgt = cur.right;

        // reached destination?
        if (r == H-1 && c == W-1) return 1;

        for (int d = 0; d < 4; d++) {
            int nr = r + dr[d];
            int nc = c + dc[d];
            if (nr < 0 || nr >= H || nc < 0 || nc >= W) continue;
            if (grid[nr][nc] == '#') continue;

            int nb, nf, nrgt;
            roll_funcs[d](b, f, rgt, &nb, &nf, &nrgt);

            // bottom must match cell number
            if (nb != grid[nr][nc] - '0') continue;

            if (!visited[nr][nc][nb][nf][nrgt]) {
                visited[nr][nc][nb][nf][nrgt] = 1;
                State ns = {nr, nc, nb, nf, nrgt};
                queue[rear++] = ns;
            }
        }
    }
    return 0;
}

