#define MAXH 505
#define MAXW 505

typedef struct {
    int b, t, f, ba, r, l; /* bottom, top, front, back, right, left */
} Die;

typedef struct {
    int x, y, s;
} Node;

static char grid[MAXH][MAXW];
static unsigned char vis[MAXH][MAXW][24];
static Die states[24];
static int trans[24][4]; /* 0:up, 1:down, 2:left, 3:right */

static int H, W;

static Die roll_up(Die d) {
    Die n;
    n.b = d.f;
    n.t = d.ba;
    n.f = d.t;
    n.ba = d.b;
    n.r = d.r;
    n.l = d.l;
    return n;
}

static Die roll_down(Die d) {
    Die n;
    n.b = d.ba;
    n.t = d.f;
    n.f = d.b;
    n.ba = d.t;
    n.r = d.r;
    n.l = d.l;
    return n;
}

static Die roll_left(Die d) {
    Die n;
    n.b = d.r;
    n.t = d.l;
    n.r = d.t;
    n.l = d.b;
    n.f = d.f;
    n.ba = d.ba;
    return n;
}

static Die roll_right(Die d) {
    Die n;
    n.b = d.l;
    n.t = d.r;
    n.r = d.b;
    n.l = d.t;
    n.f = d.f;
    n.ba = d.ba;
    return n;
}

static int same_die(Die a, Die b) {
    return a.b == b.b && a.t == b.t && a.f == b.f &&
           a.ba == b.ba && a.r == b.r && a.l == b.l;
}

int main(void) {
    if (scanf("%d %d", &H, &W) != 2) return 0;
    for (int i = 0; i < H; i++) {
        scanf("%s", grid[i]);
    }

    /* Enumerate all 24 die orientations reachable from initial orientation */
    Die init = {6, 1, 2, 5, 3, 4};

    int qh = 0, qt = 0;
    Die q[32];
    q[qt++] = init;
    states[0] = init;
    int scnt = 1;

    while (qh < qt) {
        Die cur = q[qh++];
        Die nxts[4];
        nxts[0] = roll_up(cur);
        nxts[1] = roll_down(cur);
        nxts[2] = roll_left(cur);
        nxts[3] = roll_right(cur);

        for (int k = 0; k < 4; k++) {
            int found = 0;
            for (int i = 0; i < scnt; i++) {
                if (same_die(states[i], nxts[k])) {
                    found = 1;
                    break;
                }
            }
            if (!found) {
                states[scnt++] = nxts[k];
                q[qt++] = nxts[k];
            }
        }
    }

    for (int i = 0; i < scnt; i++) {
        trans[i][0] = trans[i][1] = trans[i][2] = trans[i][3] = -1;
        Die nxts[4];
        nxts[0] = roll_up(states[i]);
        nxts[1] = roll_down(states[i]);
        nxts[2] = roll_left(states[i]);
        nxts[3] = roll_right(states[i]);
        for (int k = 0; k < 4; k++) {
            for (int j = 0; j < scnt; j++) {
                if (same_die(states[j], nxts[k])) {
                    trans[i][k] = j;
                    break;
                }
            }
        }
    }

    /* Start cell must be valid as well */
    if (grid[0][0] == '#') {
        puts("No");
        return 0;
    }
    if (grid[0][0] - '0' != init.b) {
        puts("No");
        return 0;
    }

    static Node bfs[MAXH * MAXW * 24];
    qh = qt = 0;
    vis[0][0][0] = 1;
    bfs[qt++] = (Node){0, 0, 0};

    int dx[4] = {-1, 1, 0, 0};
    int dy[4] = {0, 0, -1, 1};

    while (qh < qt) {
        Node cur = bfs[qh++];
        if (cur.x == H - 1 && cur.y == W - 1) {
            puts("Yes");
            return 0;
        }

        for (int dir = 0; dir < 4; dir++) {
            int nx = cur.x + dx[dir];
            int ny = cur.y + dy[dir];
            if (nx < 0 || nx >= H || ny < 0 || ny >= W) continue;
            if (grid[nx][ny] == '#') continue;

            int ns = trans[cur.s][dir];
            int need = grid[nx][ny] - '0';
            if (states[ns].b != need) continue;

            if (!vis[nx][ny][ns]) {
                vis[nx][ny][ns] = 1;
                bfs[qt++] = (Node){nx, ny, ns};
            }
        }
    }

    puts("No");
    return 0;
}

