struct State {
    int r, c, top, front, right;
};

// Given top, front, right, return bottom, back, left
pair<int, pair<int,int>> getFaces(int top, int front, int right) {
    int bottom = 7 - top;
    int back = 7 - front;
    int left = 7 - right;
    return {bottom, {back, left}};
}

// Roll in direction d: 0=up,1=down,2=left,3=right
State roll(const State& s, int d) {
    int top = s.top, front = s.front, right = s.right;
    int bottom = 7 - top, back = 7 - front, left = 7 - right;
    if (d == 0) { // up
        return {s.r-1, s.c, front, bottom, right};
    } else if (d == 1) { // down
        return {s.r+1, s.c, back, top, right};
    } else if (d == 2) { // left
        return {s.r, s.c-1, right, front, top};
    } else { // right
        return {s.r, s.c+1, left, front, bottom};
    }
}

