public class Main {
    // Directions: 0=up, 1=right, 2=down, 3=left
    static final int[] dr = {-1, 0, 1, 0};
    static final int[] dc = {0, 1, 0, -1};

    // Dice state: bottom, front, right
    // We'll encode state as a single integer: bottom*36 + front*6 + right
    // Since each face is 1-6, total states = 6*6*6 = 216, but only 24 are reachable
    // We'll just use 216 for simplicity.

    static int encode(int bottom, int front, int right) {
        return bottom * 36 + front * 6 + right;
    }

    // Rotate die in given direction, return new {bottom, front, right}
    static int[] roll(int bottom, int front, int right, int dir) {
        int top = 7 - bottom;
        int back = 7 - front;
        int left = 7 - right;

        int nb, nf, nr;
        switch (dir) {
            case 0: // up
                nb = front;
                nf = top;
                nr = right;
                break;
            case 1: // right
                nb = left;
                nf = front;
                nr = bottom;
                break;
            case 2: // down
                nb = back;
                nf = bottom;
                nr = right;
                break;
            case 3: // left
                nb = right;
                nf = front;
                nr = top;
                break;
            default:
                throw new RuntimeException("Invalid direction");
        }
        return new int[]{nb, nf, nr};
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int H = Integer.parseInt(st.nextToken());
        int W = Integer.parseInt(st.nextToken());

        char[][] grid = new char[H][W];
        for (int i = 0; i < H; i++) {
            grid[i] = br.readLine().toCharArray();
        }

        // BFS: state = (r, c, bottom, front, right)
        // visited for each cell and die orientation
        boolean[][][][] visited = new boolean[H][W][7][7];
        // We only need bottom and front to determine orientation, but we'll store all for simplicity
        // Actually we need bottom and front to know the full orientation, right is determined.
        // But we'll store bottom, front, right for clarity.
        // We'll use a 3D visited per cell: visited[r][c][bottom][front] is enough.
        // Let's use that to save memory.
        boolean[][][][] vis = new boolean[H][W][7][7];

        Queue<int[]> q = new ArrayDeque<>();
        // Initial: bottom=6, front=2, right=3
        q.add(new int[]{0, 0, 6, 2, 3});
        vis[0][0][6][2] = true;

        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int r = cur[0], c = cur[1];
            int bottom = cur[2], front = cur[3], right = cur[4];

            if (r == H-1 && c == W-1) {
                System.out.println("Yes");
                return;
            }

            for (int dir = 0; dir < 4; dir++) {
                int nr = r + dr[dir];
                int nc = c + dc[dir];
                if (nr < 0 || nr >= H || nc < 0 || nc >= W) continue;
                if (grid[nr][nc] == '#') continue;

                int[] next = roll(bottom, front, right, dir);
                int nb = next[0], nf = next[1], nr2 = next[2];

                // Check bottom matches target cell number
                int targetNum = grid[nr][nc] - '0';
                if (nb != targetNum) continue;

                if (!vis[nr][nc][nb][nf]) {
                    vis[nr][nc][nb][nf] = true;
                    q.add(new int[]{nr, nc, nb, nf, nr2});
                }
            }
        }

        System.out.println("No");
    }
}

