        return new int[]{d[2], d[3], d[1], d[0], d[4], d[5]};
    }

    static int[] rollDown(int[] d) {  // move to row+1
        return new int[]{d[3], d[2], d[0], d[1], d[4], d[5]};
    }

    static int[] rollLeft(int[] d) {  // move to col-1
        return new int[]{d[5], d[4], d[2], d[3], d[0], d[1]};
    }

    static int[] rollRight(int[] d) { // move to col+1
        return new int[]{d[4], d[5], d[2], d[3], d[1], d[0]};
    }

    static void buildOrientations() {
        orientations = new int[24][6];
        oriId = new HashMap<>();
        Queue<int[]> q = new ArrayDeque<>();

        int[] start = {1, 6, 2, 5, 4, 3}; // top,bottom,front,back,left,right
        q.add(start);
        oriId.put(key(start), 0);
        orientations[0] = start;

        int cnt = 1;
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int[][] nexts = {rollUp(cur), rollDown(cur), rollLeft(cur), rollRight(cur)};
            for (int[] nx : nexts) {
                String k = key(nx);
                if (!oriId.containsKey(k)) {
                    oriId.put(k, cnt);
                    orientations[cnt] = nx;
                    cnt++;
                    q.add(nx);
                }
            }
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int H = fs.nextInt();
        int W = fs.nextInt();
        char[][] grid = new char[H][];
        for (int i = 0; i < H; i++) {
            grid[i] = fs.next().toCharArray();
        }

        buildOrientations();

        if (grid[0][0] == '#' || grid[H - 1][W - 1] == '#') {
            System.out.println("No");
            return;
        }

        // initial bottom must match starting cell as well
        if (grid[0][0] != (char)('0' + 6)) {
            System.out.println("No");
            return;
        }

        boolean[][][] vis = new boolean[H][W][24];
        Queue<State> q = new ArrayDeque<>();
        int startOri = oriId.get(key(new int[]{1, 6, 2, 5, 4, 3}));
        vis[0][0][startOri] = true;
        q.add(new State(0, 0, startOri));

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (!q.isEmpty()) {
            State cur = q.poll();
            if (cur.r == H - 1 && cur.c == W - 1) {
                System.out.println("Yes");
                return;
            }

            int[] d = orientations[cur.ori];

            for (int dir = 0; dir < 4; dir++) {
                int nr = cur.r + dr[dir];
                int nc = cur.c + dc[dir];
                if (nr < 0 || nr >= H || nc < 0 || nc >= W) continue;
                if (grid[nr][nc] == '#') continue;

                int[] nd;
                if (dir == 0) nd = rollUp(d);
                else if (dir == 1) nd = rollDown(d);
                else if (dir == 2) nd = rollLeft(d);
                else nd = rollRight(d);

                int bottom = nd[1];
                if (grid[nr][nc] != (char)('0' + bottom)) continue;

                int nid = oriId.get(key(nd));
                if (!vis[nr][nc][nid]) {
                    vis[nr][nc][nid] = true;
                    q.add(new State(nr, nc, nid));
                }
            }
        }

        System.out.println("No");
    }
}

from collections import deque

H, W = map(int, input().split())
grid = [input().strip() for _ in range(H)]

# Dice rotations: given (bottom, front, right), produce new state
def roll_north(b, f, r):
    # bottom becomes front, front becomes 7-bottom, right unchanged
    return (f, 7 - b, r)

def roll_south(b, f, r):
    # bottom becomes 7-front, front becomes bottom
    return (7 - f, b, r)

def roll_east(b, f, r):
    # bottom becomes right, right becomes 7-bottom
    return (r, f, 7 - b)

def roll_west(b, f, r):
    # bottom becomes 7-right, right becomes bottom
    return (7 - r, f, b)

# BFS
# Starting state: bottom=6, front=2, right=3
